/* the flux of the trap: B(t) over two ripple periods against the 0.3 T line (box 640 × 330) */
function PE_Bplot(N,col,lab){
 const yb=290,k=1600,y=B=>yb-(B-0.19)*k;   /* 0.19 T at the axis, 0.33 T near the top */
 const pts=PE_fn(t=>PE_B(N)(t),0,20,70,560,0,-1).map(([x,B])=>[x,y(B)]);
 return PE_L(70,yb,560,yb,PE_AX,2)+PE_L(70,y(0.3),530,y(0.3),PE_INK,2,'stroke-dasharray="8 6"')+PE_T(540,y(0.3)+8,'0.3 T',{fs:22,fw:800,fill:PE_INK})
  +PE_poly(pts,col,5)+PE_T(70,40,lab,{fs:24,fw:800,fill:col})+PE_T(70,318,'two ripple periods, 20 µs',{fs:22,fill:PE_MUT});
}
function EXTRA(R,ICON){
 /* hook: a phone charger, and its switch: square pulses at 100 kHz with a little heat at every edge */
 ICON.peCharger=(x,y)=>`<g transform="translate(${x-170} ${y-120})"><rect x="60" y="40" width="200" height="170" rx="26" fill="#FFFFFF" stroke="${PE_INK}" stroke-width="4"/><rect x="110" y="10" width="18" height="34" rx="4" fill="${PE_MUT}"/><rect x="192" y="10" width="18" height="34" rx="4" fill="${PE_MUT}"/><path d="M160 210 C160 250 240 240 300 236" fill="none" stroke="${PE_INK}" stroke-width="6" stroke-linecap="round"/>${PE_T(160,120,'100 kHz',{fs:30,fw:800,a:'middle',fill:BLU})}${PE_T(160,160,'switch inside',{fs:22,fw:700,a:'middle',fill:PE_MUT})}</g>`;
 ICON.pePulses=(x,y)=>`<g transform="translate(${x-190} ${y-70})">${PE_poly([[0,110],[40,110],[40,40],[100,40],[100,110],[160,110],[160,40],[220,40],[220,110],[280,110],[280,40],[340,40],[340,110],[380,110]],GRN,5)}${[40,100,160,220,280,340].map(xx=>`<path d="M${xx-8} 30 q8 -14 0 -26 M${xx+6} 30 q8 -14 0 -26" fill="none" stroke="${RED}" stroke-width="3" stroke-linecap="round"/>`).join('')}${PE_T(190,150,'heat at every edge',{fs:24,fw:800,a:'middle',fill:RED})}</g>`;
 /* recap pictures, each about 420 × 330 */
 ICON.peSoft=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${PE_L(10,150,410,150,PE_AX,2)}${PE_poly([[10,40],[90,40],[190,150],[410,150]],BLU,6)}${PE_poly([[10,150],[250,150],[250,90],[410,90]],GRN,6)}${PE_T(120,80,'v → 0',{fs:28,fw:800,fill:BLU})}${PE_T(262,80,'then gate',{fs:26,fw:800,fill:GRN})}${PE_L(10,310,410,310,PE_AX,2)}${PE_poly([[10,200],[90,200],[190,310],[410,310]],ORG,6)}${PE_poly([[10,250],[250,250],[250,310],[410,310]],GRN,6)}${PE_T(120,240,'i → 0',{fs:28,fw:800,fill:ORG})}${PE_T(262,238,'then off',{fs:26,fw:800,fill:GRN})}</g>`;
 ICON.peGap=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${PE_core(40,30,300,280,44)}${[0,1,2,3,4,5].map(k=>`<circle cx="22" cy="${90+k*36}" r="11" fill="#E2F4EC" stroke="${GRN}" stroke-width="3"/><circle cx="92" cy="${90+k*36}" r="11" fill="#E2F4EC" stroke="${GRN}" stroke-width="3"/>`).join('')}<rect x="306" y="148" width="34" height="44" fill="${YEL}"/>${PE_T(360,180,'gap',{fs:30,fw:800,fill:ORG})}</g>`;
 ICON.peESR=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${PE_T(10,60,'C term',{fs:28,fw:800,fill:BLU})}<rect x="10" y="76" width="${15*3.3}" height="56" rx="8" fill="${BLU}"/>${PE_T(70,116,'15 mV',{fs:28,fw:800,fill:BLU})}${PE_T(10,200,'ESR term',{fs:28,fw:800,fill:RED})}<rect x="10" y="216" width="${120*3.3}" height="56" rx="8" fill="${RED}"/>${PE_T(390,256,'120 mV',{fs:28,fw:800,a:'end',fill:'#FFFFFF'})}</g>`;
}
